package assessment;
import java.nio.file.*;
import java.util.*;
import static assessment.BetaServerTest.*;
import static assessment.AssessmentServer.map;

public final class RemoteUninstallTest {
    static Map<String,Object> req(String h,String name,String key){return map("hostId",h,"confirmationName",name,"requestKey",key);}
    static void heartbeat(String h,String token,boolean capable)throws Exception{ok("POST","/api/agent/heartbeat",map("hostId",h,"uninstallCapability",capable?"uninstall-v1":""),false,token,200);}
    static Map<String,Object> record(String id){return app.store.get("uninstall_requests",id);}
    public static void main(String[] args)throws Exception {
        root=Files.createTempDirectory("remote-uninstall-http-");Files.createDirectories(root.resolve("conf"));Properties c=new Properties();c.setProperty("seedLegacyHost","false");c.setProperty("adminSalt","fixture-salt");c.setProperty("adminPasswordSha256",InventoryStore.hash("fixture-saltfixture-password"));c.setProperty("hostId","unused-fixture");c.setProperty("agentToken","unused-fixture");try(var out=Files.newOutputStream(root.resolve("conf/server.properties"))){c.store(out,"fixture");}
        try{start();String code=(String)ok("POST","/api/enrollments",map("label","fixture","maxUses",10,"autoCollect",false),true,null,201).get("enrollmentToken");var first=ok("POST","/api/agent/register",registration("uninstall-fixture-001"),false,code,200);var second=ok("POST","/api/agent/register",registration("uninstall-fixture-002"),false,code,200);String h=(String)first.get("hostId"),t=(String)first.get("agentToken"),h2=(String)second.get("hostId"),t2=(String)second.get("agentToken"),name="uninstall-fixture-001";
            check(call("POST","/api/hosts/uninstall",req(h,name,"request-fixture-0001"),false,null).code()==401,"session required");String valid=csrf;csrf="invalid";check(call("POST","/api/hosts/uninstall",req(h,name,"request-fixture-0001"),true,null).code()==403,"CSRF required");csrf=valid;
            check(call("POST","/api/hosts/uninstall",req(h,name,"request-fixture-0001"),true,null).code()==409,"old agent incompatible");heartbeat(h,t,true);
            check(call("POST","/api/hosts/uninstall",req(h,name.toUpperCase(),"request-fixture-0001"),true,null).code()==400,"exact name");var arbitrary=req(h,name,"request-fixture-0001");arbitrary.put("command","rm -rf /");check(call("POST","/api/hosts/uninstall",arbitrary,true,null).code()==400,"arbitrary command refused");
            var r=ok("POST","/api/hosts/uninstall",req(h,name,"request-fixture-0001"),true,null,202);String id=(String)r.get("id");check(id.equals(ok("POST","/api/hosts/uninstall",req(h,name,"request-fixture-0001"),true,null,202).get("id")),"duplicate request idempotent");check(call("POST","/api/hosts/uninstall",req(h,name,"request-fixture-0002"),true,null).code()==409,"overlap blocked");check(call("POST","/api/jobs",map("hostId",h),true,null).code()==409,"assessment blocked");check(ok("GET","/api/agent/poll?hostId="+h,null,false,t,200).get("action")==null,"old poll never receives action");check(ok("GET","/api/agent/poll?hostId="+h2+"&capability=uninstall-v1",null,false,t2,200).get("action")==null,"other host isolated");check(call("POST","/api/agent/uninstall/claim",map("hostId",h,"requestId",id),false,t2).code()==403,"cross host claim denied");ok("POST","/api/hosts/uninstall/cancel",map("hostId",h,"requestId",id),true,null,200);check(Boolean.FALSE.equals(ok("POST","/api/agent/uninstall/claim",map("hostId",h,"requestId",id),false,t,200).get("executable")),"cancelled cannot execute");
            r=ok("POST","/api/hosts/uninstall",req(h,name,"request-fixture-expired"),true,null,202);id=(String)r.get("id");var expired=record(id);expired.put("expiresMillis",0L);app.store.put("uninstall_requests",expired);check(Boolean.FALSE.equals(ok("POST","/api/agent/uninstall/claim",map("hostId",h,"requestId",id),false,t,200).get("executable")),"expired cannot execute");ok("GET","/api/agent/poll?hostId="+h,null,false,t,200);check("EXPIRED".equals(record(id).get("status")),"expired status");
            // A running collection may finish, but removal cannot claim/lease concurrently.
            String job=queue(h);poll(h,t,job);r=ok("POST","/api/hosts/uninstall",req(h,name,"request-fixture-0003"),true,null,202);id=(String)r.get("id");check(ok("GET","/api/agent/poll?hostId="+h+"&capability=uninstall-v1",null,false,t,200).get("action")==null,"running collection blocks delivery");check(call("POST","/api/agent/uninstall/claim",map("hostId",h,"requestId",id),false,t).code()==409,"running collection blocks claim");ok("POST","/api/agent/results",snapshot(h,job,"uninstall-inventory-event",AssessmentServer.now()),false,t,200);long inventory=app.store.scalar("SELECT count(*) FROM inventory WHERE host_id=?",h);
            stop();start();check("WAITING".equals(record(id).get("status")),"request durable after restart");var action=obj(ok("GET","/api/agent/poll?hostId="+h+"&capability=uninstall-v1",null,false,t,200).get("action"));check(UninstallRegistry.TYPE.equals(action.get("type")),"typed action");var claim=ok("POST","/api/agent/uninstall/claim",map("hostId",h,"requestId",id),false,t,200);String completion=(String)claim.get("completionToken");check(completion.equals(ok("POST","/api/agent/uninstall/claim",map("hostId",h,"requestId",id),false,t,200).get("completionToken")),"claim retry stable credential");check(call("POST","/api/hosts/uninstall/cancel",map("hostId",h,"requestId",id),true,null).code()==409,"claimed cannot cancel");
            var pending=record(id);pending.put("claimedMillis",System.currentTimeMillis()-1801000L);app.store.put("uninstall_requests",pending);new UninstallRegistry(app.store,new EnrollmentRegistry(app.store)).maintain();check("UNCONFIRMED".equals(record(id).get("status")),"silence not success");check("active".equals(new EnrollmentRegistry(app.store).credentialStatus(h)),"unconfirmed retains credential");stop();start();
            var done=map("hostId",h,"requestId",id,"outcome","SUCCEEDED","verification","OWN_FILES_AND_SCHEDULER_ABSENT_V1");check(call("POST","/api/agent/uninstall/complete",done,false,t).code()==401,"normal credential cannot confirm");done.put("verification","no-heartbeat");check(call("POST","/api/agent/uninstall/complete",done,false,completion).code()==400,"absence not verification");done.put("verification","OWN_FILES_AND_SCHEDULER_ABSENT_V1");
            app.store.exec("CREATE TRIGGER uninstall_fail BEFORE UPDATE ON identities BEGIN SELECT RAISE(ABORT,'fixture'); END");check(call("POST","/api/agent/uninstall/complete",done,false,completion).code()==500,"transaction failure not acknowledged");check("UNCONFIRMED".equals(record(id).get("status")),"outcome rollback atomic");app.store.exec("DROP TRIGGER uninstall_fail");ok("POST","/api/agent/uninstall/complete",done,false,completion,200);stop();start();ok("POST","/api/agent/uninstall/complete",done,false,completion,200);check(call("POST","/api/agent/heartbeat",map("hostId",h),false,t).code()==401,"revoked after success");check(app.store.scalar("SELECT count(*) FROM inventory WHERE host_id=?",h)==inventory,"inventory preserved");var view=ok("GET","/api/state?view=machine&hostId="+h,null,true,null,200);check(!Json.stringify(view).contains(completion),"completion secret not exposed");check(((Number)obj(view.get("presence")).get("uninstalled")).intValue()==1,"removed from active indicators");check(((Number)obj(view.get("summary")).get("activeAgents")).intValue()==0,"uninstalled excluded from active metric");done.put("outcome","FAILED");check(call("POST","/api/agent/uninstall/complete",done,false,completion).code()==409,"conflicting terminal result rejected");
            heartbeat(h2,t2,true);r=ok("POST","/api/hosts/uninstall",req(h2,"uninstall-fixture-002","request-fixture-failed"),true,null,202);id=(String)r.get("id");claim=ok("POST","/api/agent/uninstall/claim",map("hostId",h2,"requestId",id),false,t2,200);ok("POST","/api/agent/uninstall/complete",map("hostId",h2,"requestId",id,"outcome","FAILED"),false,(String)claim.get("completionToken"),200);check("active".equals(new EnrollmentRegistry(app.store).credentialStatus(h2)),"failure does not revoke");
            System.out.println("RemoteUninstallTest PASS: authentication, CSRF, typed action, legacy, expiry/cancel, ownership, duplicates, collection race, SQLite restart, atomic rollback, unconfirmed, lost ACK retry, revocation, history, failure.");
        }finally{stop();}
    }
}
